import fs from 'fs';
import path from 'path';
import type { RivetPage, RivetPageHead } from '../types/rivet-page-types';
import { composeRivetPage } from './rivetPageDocument';
import { DIST_UI_PATH } from './uiDistPath';

export const RIVET_PAGE_SHELL_DIRECTORY = path.join(DIST_UI_PATH, 'pages');
const SHARED_SHELL_FILE = 'rivet-page.html';
const EMPTY_PROJECT_SHELL_FILE = 'empty-project.html';
export const RIVET_PAGE_SHELL_FILES = [
  SHARED_SHELL_FILE,
  EMPTY_PROJECT_SHELL_FILE,
];

const shellFileFor = (page: RivetPage): string =>
  page.kind === 'empty-project' ? EMPTY_PROJECT_SHELL_FILE : SHARED_SHELL_FILE;

export const renderRivetPage = (args: {
  page: RivetPage;
  head: RivetPageHead;
}): string =>
  composeRivetPage({
    shell: fs.readFileSync(
      path.join(RIVET_PAGE_SHELL_DIRECTORY, shellFileFor(args.page)),
      'utf8',
    ),
    ...args,
  });
